(()=>{'use strict';const s=document.querySelector('.cinema'),$=q=>s.querySelector(q),stage=$('.cinema-stage'),photos=[...s.querySelectorAll('.cinema-photo')],steps=[...s.querySelectorAll('[data-cinema-step]')],paths=[...s.querySelectorAll('[data-path]')],reduce=matchMedia('(prefers-reduced-motion:reduce)'),stops=[0,.23,.46,.70,.94];let frame=0,previous=-1,sent=false;
const texts=[['DAY 01 / CLIENT DISCUSSIONS','Be there.\nKeep what matters.','Alex is planning a product launch. Three conversations. One project to move forward.','CAPTURE / ON YOUR TERMS','Double-press to start and end recording.\nPress once to mark a moment.','VOCCI / CONTEXT INPUT'],['DAY 01 / A VENUE DETAIL','The small details.\nStill with you.','A narrow entrance. A shorter setup window. Alex marks the moment, then stays in the discussion.','MEETING CONTEXT / MARKED','“We need the revised proposal by Friday.”\n“Check the entrance and setup window.”','ONE PRESS / HIGHLIGHT'],['THAT EVENING / BACK AT THE HOTEL','Your AI.\nThe full context.','After syncing Vocci, Alex asks his connected ChatGPT to build actions for creative, spatial design and production.','','','VOCCI → CHATGPT / MCP'],['DAY 02 / ON THE WAY TO THE AIRPORT','A task in mind?\nAsk Vocci AI.','Alex long-presses the ring to ask Maya for an initial assessment of yesterday’s venue constraints.','','','PRESS + HOLD / VOICE INTENT'],['VOCCI AI / REVIEW & CONFIRM','A clear request.\nReady for Maya.','Check the recipient and message in Vocci AI. The same context carries the next task forward.','','','VOCCI AI → SLACK']];
const ringPoints=[[.585,.466],[.625,.694],[.460,.505]];
function render(){frame=0;const r=s.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,s.offsetHeight-stage.offsetHeight))),v=p*4;let i=Math.min(3,Math.floor(v)),t=v-i;if(p===1){i=3;t=1}const beat=p<.13?0:p<.35?1:p<.59?2:p<.83?3:4;
const a=p<.35?0:p<.59?1:2;photos.forEach((im,j)=>{let opacity=j===a?1:0;const next=a===0?1:2;let blend=0;if(p>.30&&p<.40)blend=(p-.30)/.10;if(p>.54&&p<.64)blend=(p-.54)/.10;if(p>.30&&p<.40)opacity=j===0?1-blend:j===1?blend:0;if(p>.54&&p<.64)opacity=j===1?1-blend:j===2?blend:0;im.style.opacity=opacity;im.style.filter=reduce.matches?'none':`blur(${(1-opacity)*12}px)`;const zoom=reduce.matches?1:j===0?1+p*.52:j===1?1+(p-.35)*.35:1+(p-.59)*.32;im.style.transform=`translate3d(${j===0?-p*25:0}px,0,0) scale(${zoom})`;});
if(beat!==previous){previous=beat;s.dataset.scene=beat;const c=texts[beat];$('#cinema-location').textContent=c[0];$('#cinema-title').innerText=sent&&beat===4?'Sent.\nKeep moving.':c[1];$('#cinema-body').textContent=c[2];$('#cinema-support-label').textContent=c[3];$('#cinema-support-line').innerText=c[4];$('#cinema-ring-note').textContent=c[5];$('#cinema-context').hidden=beat>1;$('#cinema-brief').hidden=beat!==2;$('#cinema-app').hidden=beat<3;$('.cinema-send').hidden=beat!==4||sent;$('#cinema-reply-text').textContent=sent&&beat===4?'Sent to Maya in Slack. ✓':beat===4?'Ready for your confirmation.':'I’ll prepare that using yesterday’s venue discussion.';steps.forEach((b,k)=>{if(k===beat)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});paths.forEach((b,k)=>b.setAttribute('aria-current',String(k===(beat<3?0:1))));}
const ir=photos[a].getBoundingClientRect(),sr=stage.getBoundingClientRect(),iw=Math.min(ir.width,ir.height*1.5),ih=iw/1.5,point=ringPoints[a];$('.cinema-focal').style.left=((ir.left+(ir.width-iw)/2+iw*point[0]-sr.left)/sr.width*100)+'%';$('.cinema-focal').style.top=((ir.bottom-ih+ih*point[1]-sr.top)/sr.height*100)+'%';
$('.cinema-timeline i').style.width=p*100+'%';const entry=Math.max(0,Math.min(1,1-r.top/innerHeight));stage.style.setProperty('--entry-scale',reduce.matches?1:.94+.06*entry);stage.style.setProperty('--entry-radius',(1-entry)*28+'px')}
function queue(){if(!frame)frame=requestAnimationFrame(render)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);photos.forEach(im=>im.addEventListener('load',queue));function go(i){scrollTo({top:s.getBoundingClientRect().top+scrollY+stops[i]*(s.offsetHeight-stage.offsetHeight),behavior:reduce.matches?'instant':'smooth'})}steps.forEach(b=>b.addEventListener('click',()=>go(+b.dataset.cinemaStep)));paths.forEach(b=>b.addEventListener('click',()=>go(+b.dataset.path)));const dialog=document.querySelector('#cinema-review-dialog');$('#cinema-review').addEventListener('click',()=>dialog.showModal());document.querySelector('#cinema-close').addEventListener('click',()=>dialog.close());$('#cinema-send').addEventListener('click',()=>{sent=true;previous=-1;render()});render()})();
